    font-size: 0.75rem;
    color: var(--text-muted);
    margin-top: 0.25rem;
}

.error-message {
    font-size: 0.875rem;
    color: var(--error-color);
    margin-top: 0.25rem;
    font-weight: 500;
}

.error-message::before {
    content: "Error: ";
    font-weight: 700;
}

button {
    width: 100%;
    background-color: var(--primary-color);
    color: white;
    padding: 0.75rem 1.5rem;
    border: none;
    border-radius: var(--radius);
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    transition: background-color 0.2s;
}

button:hover {
    background-color: var(--primary-hover);
}

button:focus {
    outline: 2px solid transparent;
    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.4);
}

.status-message {
    margin-top: 1.5rem;
    padding: 1rem;
    border-radius: var(--radius);
    font-weight: 500;
    text-align: center;
}

.status-message.success {
    background-color: #dcfce7;
    color: #166534;
}

@media (max-width: 640px) {
    .contact-container {
        padding: 1.5rem;
    }
}
