global.HTMLImageElement = window.HTMLImageElement;
global.HTMLScriptElement = window.HTMLScriptElement;
global.HTMLLinkElement = window.HTMLLinkElement;
global.HTMLStyleElement = window.HTMLStyleElement;
global.HTMLHeadElement = window.HTMLHeadElement;
global.HTMLBodyElement = window.HTMLBodyElement;
global.HTMLHtmlElement = window.HTMLHtmlElement;
global.NodeList = window.NodeList;
global.HTMLCollection = window.HTMLCollection;
global.CharacterData = window.CharacterData;
global.Text = window.Text;
global.Location = window.Location;
global.History = window.History;
global.Navigator = window.Navigator;
global.navigator = window.navigator;
global.CustomEvent = window.CustomEvent;

axe.run(document, (err, results) => {
    if (err) {
        console.error(err);
        process.exit(1);
    }
    if (results.violations.length > 0) {
        console.log('Violations found:');
        console.log(JSON.stringify(results.violations, null, 2));
        process.exit(1);
    } else {
        console.log('No accessibility violations found!');
