    margin-top: 1.5rem;
    padding: 1rem;
    border-radius: var(--radius);
    font-weight: 500;
    text-align: center;
}

.status-message.success {
    background-color: #dcfce7;
    color: #166534;
}

@media (max-width: 640px) {
